const missing=required.filter(k=>!stages[k]);
const qa=stages.fact_production_qa?.result||{};
return [{json:{run_id:i.run_id,project:'AquaPilot',artifact:'flyer',complete:missing.length===0,missing_stages:missing,qa_verdict:qa.verdict||'NOT_PROVIDED',production_package:{campaign_brief:stages.campaign_lead?.result,product_truth:stages.product_expert?.result,audience:stages.audience_researcher?.result,positioning:stages.positioning_strategist?.result,persuasion:stages.behavioral_marketing?.result,copy:stages.conversion_copywriter?.result,information_architecture:stages.information_architect?.result,art_direction:stages.art_director?.result,design_specification:stages.graphic_designer?.result,red_team:stages.red_team_skeptical_buyer?.result,qa:stages.fact_production_qa?.result},source_ref:i.source_ref}}];
